// Raw keyboard state by `KeyboardEvent.code`. Prevents the page from scrolling on game keys.

const PREVENT_DEFAULT = new Set([
  'Space',
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'Tab',
]);

export class KeyboardSource {
  constructor(target = window) {
    this.target = target;
    this.down = new Set();
    this.lastActivity = 0;

    this._onKeyDown = (e) => {
      if (PREVENT_DEFAULT.has(e.code)) e.preventDefault();
      if (e.repeat) return;
      this.down.add(e.code);
      this.lastActivity = performance.now();
    };
    this._onKeyUp = (e) => {
      if (PREVENT_DEFAULT.has(e.code)) e.preventDefault();
      this.down.delete(e.code);
    };
    this._onBlur = () => {
      this.down.clear();
    };

    target.addEventListener('keydown', this._onKeyDown, { passive: false });
    target.addEventListener('keyup', this._onKeyUp, { passive: false });
    window.addEventListener('blur', this._onBlur);
  }

  isDown(code) {
    return this.down.has(code);
  }

  anyDown(codes) {
    for (let i = 0; i < codes.length; i++) if (this.down.has(codes[i])) return true;
    return false;
  }

  dispose() {
    this.target.removeEventListener('keydown', this._onKeyDown);
    this.target.removeEventListener('keyup', this._onKeyUp);
    window.removeEventListener('blur', this._onBlur);
    this.down.clear();
  }
}

