// EffectComposer stack: RenderPass → UnrealBloomPass → RetroPass → OutputPass.
// The composer renders into a half-float MSAA target so anti-aliasing survives post-processing and
// bloom thresholds operate on true HDR values. Tone-mapping and sRGB conversion happen once, in OutputPass.
import { Vector2, WebGLRenderTarget, HalfFloatType, Color } from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { RetroShader } from './RetroShader.js';

const _size = new Vector2();
const _color = new Color();

export class PostPipeline {
