    if (this.intensity > 0.5 && s % 4 === 2) this._hat(t);
  }

  _pad(chord, t, dur) {
    const ctx = this.audio.ctx;
    const { padFilter } = this._nodes;
    for (let i = 0; i < chord.length; i++) {
      const f = midiToFreq(chord[i]);
      for (let k = 0; k < 2; k++) {
        const osc = ctx.createOscillator();
        osc.type = 'sawtooth';
        osc.frequency.value = f;
        osc.detune.value = k === 0 ? -7 : 7;
        const g = ctx.createGain();
        g.gain.setValueAtTime(0.0001, t);
        g.gain.linearRampToValueAtTime(0.1, t + 0.35);
        g.gain.setValueAtTime(0.1, t + dur - 0.4);
        g.gain.linearRampToValueAtTime(0.0001, t + dur);
        osc.connect(g);
        g.connect(padFilter);
        osc.start(t);
        osc.stop(t + dur + 0.05);
        osc.onended = () => {
          osc.disconnect();
          g.disconnect();
        };
      }
    }
  }

  _bass(note, t, dur) {
    const ctx = this.audio.ctx;
    const osc = ctx.createOscillator();
    osc.type = 'square';
    osc.frequency.value = midiToFreq(note);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(900, t);
    filter.frequency.exponentialRampToValueAtTime(200, t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(1, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(filter);
    filter.connect(g);
    g.connect(this._nodes.bassGain);
    osc.start(t);
    osc.stop(t + dur + 0.05);
    osc.onended = () => {
      osc.disconnect();
      filter.disconnect();
      g.disconnect();
    };
  }

