/* ─────────────────────────────────────────────────────────────────────────────
   Neon Arcade — Glassmorphism design system
   Frosted panels over the 3-D scene, vibrant neon accents, no external assets.
   ───────────────────────────────────────────────────────────────────────────── */

:root {
  --bg: #05060f;
  --glass-bg: rgba(12, 14, 32, 0.42);
  --glass-bg-strong: rgba(10, 12, 28, 0.72);
  --glass-border: rgba(255, 255, 255, 0.14);
  --glass-highlight: rgba(255, 255, 255, 0.08);
  --glass-blur: 14px;
  --glass-radius: 14px;

  --neon-cyan: #19f0ff;
  --neon-magenta: #ff2bd6;
  --neon-lime: #7cff3b;
  --neon-amber: #ffb020;
  --neon-red: #ff3355;
  --neon-violet: #9b5cff;

  --text: #e8ecff;
  --text-dim: rgba(232, 236, 255, 0.58);
  --text-faint: rgba(232, 236, 255, 0.32);

  --font-ui: 'Segoe UI', 'Helvetica Neue', system-ui, -apple-system, sans-serif;
  --font-display: 'Bahnschrift', 'Segoe UI', 'Helvetica Neue', system-ui, sans-serif;
  --font-mono: 'Cascadia Mono', 'Consolas', 'SF Mono', ui-monospace, monospace;
}

* {
  box-sizing: border-box;
}

.game-canvas {
  position: absolute;
  inset: 0;
  width: 100% !important;
  height: 100% !important;
  display: block;
  outline: none;
}

/* ── Overlay root ─────────────────────────────────────────────────────────── */

.ui-root {
  position: absolute;
  inset: 0;
  pointer-events: none;
  font-family: var(--font-ui);
  color: var(--text);
  user-select: none;
  -webkit-user-select: none;
  overflow: hidden;
  z-index: 10;
}

.hidden {
  display: none !important;
}

/* ── Glass panels ─────────────────────────────────────────────────────────── */

.glass-panel {
  background: var(--glass-bg);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(140%);
  backdrop-filter: blur(var(--glass-blur)) saturate(140%);
  border: 1px solid var(--glass-border);
  border-radius: var(--glass-radius);
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 var(--glass-highlight);
}

.glass-panel.strong {
  background: var(--glass-bg-strong);
}

/* ── HUD ──────────────────────────────────────────────────────────────────── */

.hud-panel {
  position: absolute;
  padding: 10px 16px;
  min-width: 120px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  transition: opacity 0.3s ease;
}

.pos-top-left { top: 16px; left: 16px; }
.pos-top-center { top: 16px; left: 50%; transform: translateX(-50%); align-items: center; }
.pos-top-right { top: 16px; right: 16px; align-items: flex-end; }
.pos-bottom-left { bottom: 16px; left: 16px; }
.pos-bottom-center { bottom: 16px; left: 50%; transform: translateX(-50%); align-items: center; }
.pos-bottom-right { bottom: 16px; right: 16px; align-items: flex-end; }

.hud-label {
  font-size: 10px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--text-dim);
  font-weight: 600;
}

.hud-value {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0.08em;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
  color: var(--neon-cyan);
  text-shadow: 0 0 8px currentColor, 0 0 22px rgba(25, 240, 255, 0.45);
}

.hud-value.small {
  font-size: 18px;
}

.hud-row {
  display: flex;
  gap: 14px;
  align-items: baseline;
}

/* Neon text helpers */
.neon-text { text-shadow: 0 0 6px currentColor, 0 0 18px currentColor; }
.neon-cyan { color: var(--neon-cyan); }
.neon-magenta { color: var(--neon-magenta); }
.neon-lime { color: var(--neon-lime); }
.neon-amber { color: var(--neon-amber); }
.neon-red { color: var(--neon-red); }
.neon-violet { color: var(--neon-violet); }

/* Lives: tiny cannon silhouettes */
.hud-lives {
  display: flex;
  gap: 7px;
  align-items: flex-end;
  min-height: 14px;
}

.life-icon {
  width: 20px;
  height: 11px;
  background: var(--neon-cyan);
  clip-path: polygon(45% 0, 55% 0, 55% 25%, 80% 25%, 100% 55%, 100% 100%, 0 100%, 0 55%, 20% 25%, 45% 25%);
  box-shadow: 0 0 8px var(--neon-cyan);
  filter: drop-shadow(0 0 4px var(--neon-cyan));
}

/* Chips (combo / power-up) */
.chip {
  display: inline-flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 12px;
  border-radius: 10px;
  border: 1px solid var(--glass-border);
  background: rgba(255, 255, 255, 0.04);
  min-width: 110px;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-weight: 700;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.chip.off {
  opacity: 0;
  transform: translateY(6px);
}

.chip-bar {
  height: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.12);
  overflow: hidden;
}

.chip-bar > i {
  display: block;
  height: 100%;
  width: 100%;
  background: currentColor;
  box-shadow: 0 0 6px currentColor;
  transform-origin: left center;
  transform: scaleX(1);
}

/* ── Menu screens ─────────────────────────────────────────────────────────── */

.menu-screen {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  background: radial-gradient(ellipse at center, rgba(5, 6, 15, 0.15) 0%, rgba(5, 6, 15, 0.7) 100%);
  animation: fade-in 0.3s ease;
}

.menu-card {
  min-width: 380px;
  max-width: 600px;
  padding: 36px 48px 30px;
  text-align: center;
  animation: menu-in 0.4s cubic-bezier(0.2, 0.9, 0.3, 1.15);
}

.menu-eyebrow {
  font-size: 11px;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--text-dim);
  margin-bottom: 8px;
}

.menu-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: 46px;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: var(--neon-cyan);
  text-shadow: 0 0 10px currentColor, 0 0 30px rgba(25, 240, 255, 0.6), 0 0 60px rgba(25, 240, 255, 0.3);
  line-height: 1.05;
}

.menu-title.magenta { color: var(--neon-magenta); text-shadow: 0 0 10px currentColor, 0 0 30px rgba(255, 43, 214, 0.6); }
.menu-title.lime { color: var(--neon-lime); text-shadow: 0 0 10px currentColor, 0 0 30px rgba(124, 255, 59, 0.6); }
