.pos-top-left { top: 16px; left: 16px; }
.pos-top-center { top: 16px; left: 50%; transform: translateX(-50%); align-items: center; }
.pos-top-right { top: 16px; right: 16px; align-items: flex-end; }
.pos-bottom-left { bottom: 16px; left: 16px; }
.pos-bottom-center { bottom: 16px; left: 50%; transform: translateX(-50%); align-items: center; }
.pos-bottom-right { bottom: 16px; right: 16px; align-items: flex-end; }

.hud-label {
  font-size: 10px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--text-dim);
  font-weight: 600;
}

.hud-value {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0.08em;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
  color: var(--neon-cyan);
  text-shadow: 0 0 8px currentColor, 0 0 22px rgba(25, 240, 255, 0.45);
}

.hud-value.small {
  font-size: 18px;
}

.hud-row {
  display: flex;
  gap: 14px;
  align-items: baseline;
}

/* Neon text helpers */
.neon-text { text-shadow: 0 0 6px currentColor, 0 0 18px currentColor; }
.neon-cyan { color: var(--neon-cyan); }
.neon-magenta { color: var(--neon-magenta); }
.neon-lime { color: var(--neon-lime); }
.neon-amber { color: var(--neon-amber); }
.neon-red { color: var(--neon-red); }
.neon-violet { color: var(--neon-violet); }

/* Lives: tiny cannon silhouettes */
.hud-lives {
  display: flex;
  gap: 7px;
  align-items: flex-end;
  min-height: 14px;
}

.life-icon {
  width: 20px;
  height: 11px;
  background: var(--neon-cyan);
  clip-path: polygon(45% 0, 55% 0, 55% 25%, 80% 25%, 100% 55%, 100% 100%, 0 100%, 0 55%, 20% 25%, 45% 25%);
  box-shadow: 0 0 8px var(--neon-cyan);
  filter: drop-shadow(0 0 4px var(--neon-cyan));
}

/* Chips (combo / power-up) */
.chip {
  display: inline-flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 12px;
  border-radius: 10px;
  border: 1px solid var(--glass-border);
  background: rgba(255, 255, 255, 0.04);
  min-width: 110px;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-weight: 700;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.chip.off {
  opacity: 0;
  transform: translateY(6px);
}

.chip-bar {
  height: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.12);
  overflow: hidden;
}

.chip-bar > i {
  display: block;
  height: 100%;
  width: 100%;
  background: currentColor;
  box-shadow: 0 0 6px currentColor;
  transform-origin: left center;
  transform: scaleX(1);
}

/* ── Menu screens ─────────────────────────────────────────────────────────── */

.menu-screen {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  background: radial-gradient(ellipse at center, rgba(5, 6, 15, 0.15) 0%, rgba(5, 6, 15, 0.7) 100%);
  animation: fade-in 0.3s ease;
}

.menu-card {
  min-width: 380px;
  max-width: 600px;
  padding: 36px 48px 30px;
  text-align: center;
  animation: menu-in 0.4s cubic-bezier(0.2, 0.9, 0.3, 1.15);
}

.menu-eyebrow {
  font-size: 11px;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--text-dim);
  margin-bottom: 8px;
}

.menu-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: 46px;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: var(--neon-cyan);
  text-shadow: 0 0 10px currentColor, 0 0 30px rgba(25, 240, 255, 0.6), 0 0 60px rgba(25, 240, 255, 0.3);
  line-height: 1.05;
}

.menu-title.magenta { color: var(--neon-magenta); text-shadow: 0 0 10px currentColor, 0 0 30px rgba(255, 43, 214, 0.6); }
.menu-title.lime { color: var(--neon-lime); text-shadow: 0 0 10px currentColor, 0 0 30px rgba(124, 255, 59, 0.6); }
.menu-title.red { color: var(--neon-red); text-shadow: 0 0 10px currentColor, 0 0 30px rgba(255, 51, 85, 0.6); }
.menu-title.amber { color: var(--neon-amber); text-shadow: 0 0 10px currentColor, 0 0 30px rgba(255, 176, 32, 0.6); }

.menu-subtitle {
  margin: 8px 0 22px;
  font-size: 13px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--neon-magenta);
  text-shadow: 0 0 10px rgba(255, 43, 214, 0.6);
}

.menu-body {
  margin: 0 0 18px;
  color: var(--text-dim);
  font-size: 13px;
  letter-spacing: 0.06em;
  line-height: 1.6;
}

.menu-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 28px;
  margin: 6px auto 22px;
  max-width: 360px;
  text-align: left;
}

.stat {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  padding-bottom: 4px;
}

.stat-k {
  font-size: 10px;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.stat-v {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  color: var(--neon-amber);
  text-shadow: 0 0 8px rgba(255, 176, 32, 0.6);
  font-variant-numeric: tabular-nums;
}

.menu-items {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0 auto;
  max-width: 340px;
}

.menu-item {
  padding: 11px 18px;
  border: 1px solid transparent;
  border-radius: 10px;
  font-size: 14px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--text-dim);
  cursor: pointer;
  transition: color 0.15s, border-color 0.15s, background 0.15s, transform 0.15s;
}

.menu-item.active {
  color: var(--neon-magenta);
  border-color: rgba(255, 43, 214, 0.55);
  background: rgba(255, 43, 214, 0.08);
  text-shadow: 0 0 8px rgba(255, 43, 214, 0.8);
  transform: translateX(4px);
  box-shadow: 0 0 18px rgba(255, 43, 214, 0.15), inset 0 0 12px rgba(255, 43, 214, 0.05);
}

.menu-footer {
  margin-top: 24px;
  font-size: 11px;
  letter-spacing: 0.14em;
  color: var(--text-faint);
  line-height: 1.8;
}

.menu-footer kbd {
  font-family: var(--font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-dim);
  margin: 0 2px;
}

/* ── Floating text ────────────────────────────────────────────────────────── */

.float-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 9;
}

.float-text {
  position: absolute;
  left: 0;
  top: 0;
  font-family: var(--font-display);
  font-weight: 800;
  letter-spacing: 0.12em;
  white-space: nowrap;
  will-change: transform, opacity;
  text-shadow: 0 0 8px currentColor, 0 0 20px currentColor;
  opacity: 0;
}

.float-text.sm { font-size: 14px; }
.float-text.md { font-size: 20px; }
.float-text.lg { font-size: 34px; }
.float-text.xl { font-size: 54px; letter-spacing: 0.24em; }

/* ── Banner (wave intro / clear) ──────────────────────────────────────────── */

.banner {
  position: absolute;
  left: 50%;
  top: 36%;
  transform: translate(-50%, -50%);
  text-align: center;
  pointer-events: none;
  animation: banner 1.8s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}

.banner-title {
  font-family: var(--font-display);
  font-size: 58px;
  font-weight: 800;
  letter-spacing: 0.34em;
  color: var(--neon-cyan);
  text-shadow: 0 0 12px currentColor, 0 0 40px currentColor;
}

.banner-sub {
  margin-top: 6px;
  font-size: 14px;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--neon-magenta);
  text-shadow: 0 0 10px currentColor;
}

/* ── Toast ────────────────────────────────────────────────────────────────── */

.toast {
  position: absolute;
  left: 50%;
  bottom: 84px;
  transform: translateX(-50%);
  padding: 8px 18px;
  font-size: 12px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--neon-lime);
  animation: toast 1.6s ease forwards;
  pointer-events: none;
}

/* ── Hint strip ───────────────────────────────────────────────────────────── */

.hint {
  position: absolute;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  font-size: 11px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--text-faint);
  animation: blink 2s ease-in-out infinite;
  white-space: nowrap;
}

/* ── Keyframes ────────────────────────────────────────────────────────────── */

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes menu-in {
  from { opacity: 0; transform: translateY(18px) scale(0.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes banner {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(1.6); letter-spacing: 0.6em; }
  18% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  75% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -60%) scale(1.05); }
}

@keyframes toast {
  0% { opacity: 0; transform: translate(-50%, 8px); }
  15% { opacity: 1; transform: translate(-50%, 0); }
  80% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -8px); }
}

@keyframes blink {
  0%, 100% { opacity: 0.35; }
  50% { opacity: 1; }
}

@media (max-width: 720px) {
  .menu-card { min-width: 0; width: calc(100vw - 32px); padding: 26px 22px; }
  .menu-title { font-size: 30px; }
  .banner-title { font-size: 36px; }
  .hud-value { font-size: 20px; }
}

