        if (!this.demo) this.originY -= FORMATION.DROP_Y;
        this.dir = -this.dir;
        this.pendingDrop = false;
        if (!this.demo) this.events.emit('invader:drop', { originY: this.originY, lowestY: this.lowestY() });
