        this.originX += this.dir * FORMATION.STEP_X;
        const b = this.aliveBounds(this._bounds);
        const limit = WORLD.HALF_WIDTH - FORMATION.EDGE_MARGIN;
        if (
          (this.dir > 0 && b.maxX + b.maxHalfW >= limit) ||
          (this.dir < 0 && b.minX - b.maxHalfW <= -limit)
        ) {
