    if (this.comboTimer > 0) {
      this.comboTimer -= dt;
      if (this.comboTimer <= 0) {
        this.comboTimer = 0;
        this.chain = 0;
        this.multiplier = 1;
      }
    }
  }

  /** Persist the hi-score if it changed (call at game over / victory / teardown). */
  flush() {
    if (this._hiDirty) {
      saveHiScore(this.hiScore);
      this._hiDirty = false;
    }
  }
}

