1	// Synthwave backdrop: scrolling emissive grid floor, striped retro sun, fBm planet, two-layer
2	// instanced starfield, the fixed light rig, an invasion-pressure pulse light and pooled muzzle lights.
3	import {
4	  Mesh,
5	  PlaneGeometry,
6	  CircleGeometry,
7	  SphereGeometry,
8	  IcosahedronGeometry,
9	  InstancedMesh,
10	  MeshStandardMaterial,
11	  PointLight,
12	  Matrix4,
13	  Vector3,
14	  Quaternion,
15	  Color,
16	  DynamicDrawUsage,
17	} from 'three';
18	import { makeGridTexture, makeSunTexture, makePlanetTextures } from '@shared/procgen/TextureFactory.js';
19	import { floorMaterial, neonMaterial, enableInstanceEmissiveTint } from '@shared/procgen/MaterialLibrary.js';
20	import { createNeonLighting } from '@shared/render/Lighting.js';
21	import { clamp, damp } from '@shared/math/MathUtils.js';
22	import { WORLD, COLORS } from '../config.js';
23	
24	const _m = new Matrix4();
25	const _p = new Vector3();
26	const _q = new Quaternion();
27	const _s = new Vector3();
28	const _c = new Color();
29	
30	const STAR_LAYERS = [
31	  { count: 500, radius: 0.05, speed: 0.8, zMin: -80, zMax: -55 },
32	  { count: 250, radius: 0.09, speed: 1.6, zMin: -55, zMax: -30 },
33	];
34	const STAR_Y_MIN = -25;
35	const STAR_Y_MAX = 70;
36	const STAR_PALETTE = [0xffffff, 0xcfe8ff, 0x19f0ff, 0xffd6f4, 0xff2bd6, 0xfff1c2];
37	
38	export class Environment {
39	  /**
40	   * @param {import('three').Scene} scene
41	   * @param {import('@shared/core/ResourceTracker.js').ResourceTracker} tracker
42	   * @param {import('@shared/procgen/Random.js').Random} random
43	   */
44	  constructor(scene, tracker, random) {
45	    this.scene = scene;
46	    this.random = random;
47	    this.pressure = 0;
48	    this.pulseClock = 0;
49	
50	    this.lighting = createNeonLighting(scene, {
51	      keyPosition: [6, 18, 12],
52	      rimPosition: [-8, 6, -10],
53	      target: [0, WORLD.VIEW.centerY, 0],
54	    });
55	
56	    // ── Grid floor.
57	    this.gridTexture = tracker.track(makeGridTexture({ size: 1024, cells: 32, repeat: [16, 16] }));
58	    const floorGeometry = tracker.track(new PlaneGeometry(200, 200, 1, 1));
59	    this.floorMaterial = tracker.track(floorMaterial({ map: this.gridTexture, emissive: COLORS.CYAN, intensity: 0.8, roughness: 0.6, metalness: 0.3 }));
60	    this.floor = new Mesh(floorGeometry, this.floorMaterial);
61	    this.floor.rotation.x = -Math.PI * 0.5;
62	    this.floor.position.set(0, WORLD.FLOOR_Y, -30);
63	    scene.add(this.floor);
64	    tracker.track(this.floor);
65	
66	    // ── Retro sun.
67	    this.sunTexture = tracker.track(makeSunTexture({ size: 512 }));
68	    const sunGeometry = tracker.track(new CircleGeometry(14, 64));
69	    this.sunMaterial = tracker.track(
70	      new MeshStandardMaterial({
71	        map: this.sunTexture,
72	        emissiveMap: this.sunTexture,
73	        emissive: new Color(0xffffff),
74	        emissiveIntensity: 0.85,
75	        color: new Color(0x000000),
76	        transparent: true,
77	        depthWrite: false,
78	        roughness: 1,
79	        metalness: 0,
80	      }),
81	    );
82	    this.sun = new Mesh(sunGeometry, this.sunMaterial);
83	    this.sun.position.set(0, 14, -60);
84	    this.sun.renderOrder = -2;
85	    scene.add(this.sun);
86	    tracker.track(this.sun);
87	
88	    // ── Planet.
89	    const planetMaps = makePlanetTextures({ size: 512, seed: 42 });
90	    tracker.track(planetMaps.map);
91	    tracker.track(planetMaps.emissiveMap);
92	    const planetGeometry = tracker.track(new SphereGeometry(9, 48, 32));
93	    this.planetMaterial = tracker.track(
94	      new MeshStandardMaterial({
95	        map: planetMaps.map,
96	        emissiveMap: planetMaps.emissiveMap,
97	        emissive: new Color(COLORS.AMBER),
98	        emissiveIntensity: 0.9,
99	        roughness: 0.9,
100	        metalness: 0.05,
101	      }),
102	    );
103	    this.planet = new Mesh(planetGeometry, this.planetMaterial);
104	    this.planet.position.set(-28, 20, -70);
105	    this.planet.rotation.z = 0.35;
106	    scene.add(this.planet);
107	    tracker.track(this.planet);
108	
109	    // ── Starfield (two depth layers).
110	    this.starLayers = [];
111	    for (const layer of STAR_LAYERS) {
112	      const geometry = tracker.track(new IcosahedronGeometry(layer.radius, 0));
113	      const material = tracker.track(neonMaterial({ color: 0x000000, emissive: 0xffffff, intensity: 2.0, roughness: 1 }));
114	      enableInstanceEmissiveTint(material);
115	      const mesh = new InstancedMesh(geometry, material, layer.count);
116	      mesh.instanceMatrix.setUsage(DynamicDrawUsage);
117	      mesh.frustumCulled = false;
118	      _q.identity();
119	      for (let i = 0; i < layer.count; i++) {
120	        const scale = random.range(0.6, 1.6);
121	        _p.set(random.range(-90, 90), random.range(STAR_Y_MIN, STAR_Y_MAX), random.range(layer.zMin, layer.zMax));
122	        _s.set(scale, scale, scale);
123	        _m.compose(_p, _q, _s);
124	        mesh.setMatrixAt(i, _m);
125	        _c.set(random.pick(STAR_PALETTE)).multiplyScalar(random.range(0.5, 1));
126	        mesh.setColorAt(i, _c);
127	      }
128	      mesh.instanceMatrix.needsUpdate = true;
129	      mesh.instanceColor.needsUpdate = true;
130	      scene.add(mesh);
131	      tracker.track(mesh);
132	      this.starLayers.push({ mesh, speed: layer.speed, count: layer.count });
133	    }
134	
135	    // ── Dynamic lights (fixed set, intensity-modulated).
136	    this.pulseLight = new PointLight(COLORS.RED, 0, 40, 2);
137	    this.pulseLight.position.set(0, 5, 4);
138	    scene.add(this.pulseLight);
139	
140	    this.muzzleLights = [];
141	    for (let i = 0; i < 3; i++) {
142	      const light = new PointLight(COLORS.CYAN, 0, 14, 2);
143	      light.position.set(0, -50, 2);
144	      scene.add(light);
145	      this.muzzleLights.push({ light, energy: 0 });
146	    }
147	    this._muzzleCursor = 0;
148	    this.pulseIntensity = 0;
149	  }
150	
151	  /** Flash a pooled muzzle light at (x, y). */
152	  flashMuzzle(x, y, intensity = 90) {
153	    const slot = this.muzzleLights[this._muzzleCursor];
154	    this._muzzleCursor = (this._muzzleCursor + 1) % this.muzzleLights.length;
155	    slot.light.position.set(x, y, 1.5);
156	    slot.energy = intensity;
157	    slot.light.intensity = intensity;
158	  }
159	
160	  /** `pressure` ∈ [0, 1]: how close the invasion is. Drives the red pulse. */
161	  setPressure(pressure) {
162	    this.pressure = clamp(pressure, 0, 1);
163	  }
164	
165	  update(dt) {
166	    this.gridTexture.offset.y -= 0.12 * dt;
167	    if (this.gridTexture.offset.y < -1) this.gridTexture.offset.y += 1;
168	
169	    for (const layer of this.starLayers) {
170	      const mesh = layer.mesh;
171	      const dy = layer.speed * dt;
172	      for (let i = 0; i < layer.count; i++) {
173	        mesh.getMatrixAt(i, _m);
174	        let y = _m.elements[13] - dy;
175	        if (y < STAR_Y_MIN) y += STAR_Y_MAX - STAR_Y_MIN;
176	        _m.elements[13] = y;
177	        mesh.setMatrixAt(i, _m);
178	      }
179	      mesh.instanceMatrix.needsUpdate = true;
180	    }
181	
182	    this.planet.rotation.y += dt * 0.02;
183	
184	    // Invasion pulse: faster and brighter as the formation nears the cannon.
185	    this.pulseClock += dt * (1.5 + 2 * this.pressure);
186	    const target = this.pressure > 0.01 ? this.pressure * 140 * (0.5 + 0.5 * Math.sin(this.pulseClock * Math.PI * 2)) : 0;
187	    this.pulseIntensity = damp(this.pulseIntensity, target, 10, dt);
188	    this.pulseLight.intensity = this.pulseIntensity;
189	
190	    for (const slot of this.muzzleLights) {
191	      if (slot.energy > 0) {
192	        slot.energy = Math.max(0, slot.energy - dt * 700);
193	        slot.light.intensity = slot.energy;
194	      }
195	    }
196	  }
197	
198	  dispose() {
199	    this.lighting.dispose();
200	    this.scene.remove(this.pulseLight);
201	    this.pulseLight.dispose();
202	    for (const slot of this.muzzleLights) {
203	      this.scene.remove(slot.light);
204	      slot.light.dispose();
205	    }
206	    // Meshes, geometries, materials and textures are owned by the ResourceTracker.
207	  }
208	}

1	// Pooled projectiles. Player bolts are capsules with ribbon trails; invader shots come in three
2	// classic flavours (plunger, rolling, squiggly). Every bullet keeps its previous position so
3	// collision can sweep a segment rather than test a point.
4	import { Mesh, CapsuleGeometry, CylinderGeometry, BoxGeometry } from 'three';
5	import { ObjectPool } from '@shared/core/ObjectPool.js';
6	import { neonMaterial } from '@shared/procgen/MaterialLibrary.js';
7	import { mergeGeometries } from '@shared/procgen/GeometryUtils.js';
8	import { setAabb } from '@shared/math/Collision.js';
9	import { WORLD, PLAYER, BULLETS, INVADER_FIRE, COLORS } from '../config.js';
10	
11	function makeRollingGeometry() {
12	  const a = new BoxGeometry(0.3, 0.08, 0.08);
13	  const b = new BoxGeometry(0.08, 0.3, 0.08);
14	  b.translate(0, 0, 0);
15	  const c = new BoxGeometry(0.07, 0.8, 0.07);
16	  const d = new BoxGeometry(0.3, 0.08, 0.08);
17	  d.translate(0, -0.3, 0);
18	  d.rotateY(Math.PI * 0.5);
19	  a.translate(0, 0.3, 0);
20	  return mergeGeometries([a, b, c, d]);
21	}
22	
23	function makeSquigglyGeometry() {
24	  const parts = [];
25	  const segments = 9;
26	  for (let k = 0; k < segments; k++) {
27	    const t = k / (segments - 1);
28	    const y = -0.4 + t * 0.8;
29	    const x = Math.sin(t * Math.PI * 2) * 0.13;
30	    const box = new BoxGeometry(0.1, 0.12, 0.1);
31	    box.translate(x, y, 0);
32	    parts.push(box);
33	  }
34	  return mergeGeometries(parts);
35	}
36	
37	export class ProjectileSystem {
38	  /**
39	   * @param {import('three').Scene} scene
40	   * @param {import('@shared/core/ResourceTracker.js').ResourceTracker} tracker
41	   * @param {import('@shared/vfx/VFXDirector.js').VFXDirector} vfx
42	   */
43	  constructor(scene, tracker, vfx) {
44	    this.scene = scene;
45	    this.vfx = vfx;
46	
47	    this.playerGeometry = tracker.track(new CapsuleGeometry(0.08, 0.55, 4, 8));
48	    this.playerMaterial = tracker.track(neonMaterial({ color: 0x06141a, emissive: COLORS.BULLET_PLAYER, intensity: 2.0 }));
49	
50	    this.invaderGeometries = {
51	      plunger: tracker.track(new CylinderGeometry(0.1, 0.15, 0.8, 8)),
52	      rolling: tracker.track(makeRollingGeometry()),
53	      squiggly: tracker.track(makeSquigglyGeometry()),
54	    };
55	    this.invaderMaterial = tracker.track(neonMaterial({ color: 0x1a1004, emissive: COLORS.BULLET_INVADER, intensity: 1.6 }));
56	
57	    this.playerPool = new ObjectPool({
58	      capacity: BULLETS.PLAYER_POOL,
59	      create: () => {
60	        const mesh = new Mesh(this.playerGeometry, this.playerMaterial);
61	        mesh.visible = false;
62	        scene.add(mesh);
63	        return {
64	          mesh,
65	          x: 0,
66	          y: 0,
67	          prevX: 0,
68	          prevY: 0,
69	          vx: 0,
70	          vy: 0,
71	          age: 0,
72	          trail: null,
73	          halfW: PLAYER.BULLET_HALF_W,
74	          halfH: PLAYER.BULLET_HALF_H,
75	          owner: 'player',
76	        };
77	      },
78	      onRelease: (b) => {
79	        b.mesh.visible = false;
80	        if (b.trail) {
81	          this.vfx.trails.release(b.trail);
82	          b.trail = null;
83	        }
84	      },
85	    });
86	
87	    this.invaderPool = new ObjectPool({
88	      capacity: BULLETS.INVADER_POOL,
89	      create: () => {
90	        const mesh = new Mesh(this.invaderGeometries.plunger, this.invaderMaterial);
91	        mesh.visible = false;
92	        scene.add(mesh);
93	        return {
94	          mesh,
95	          x: 0,
96	          y: 0,
97	          x0: 0,
98	          prevX: 0,
99	          prevY: 0,
100	          vy: 0,
101	          age: 0,
102	          kind: 'plunger',
103	          halfW: BULLETS.INVADER_HALF_W,
104	          halfH: BULLETS.INVADER_HALF_H,
105	          owner: 'invader',
106	        };
107	      },
108	      onRelease: (b) => {
109	        b.mesh.visible = false;
110	      },
111	    });
112	  }
113	
114	  get playerLiveCount() {
115	    return this.playerPool.liveCount;
116	  }
117	
118	  get invaderLiveCount() {
119	    return this.invaderPool.liveCount;
120	  }
121	
122	  /** Fire a player bolt at `angle` radians from straight up. Returns the bullet or null. */
123	  spawnPlayer(x, y, angle = 0) {
124	    const b = this.playerPool.acquire();
125	    if (!b) return null;
126	    b.x = x;
127	    b.y = y;
128	    b.prevX = x;
129	    b.prevY = y;
130	    b.vx = Math.sin(angle) * PLAYER.BULLET_SPEED;
131	    b.vy = Math.cos(angle) * PLAYER.BULLET_SPEED;
132	    b.age = 0;
133	    b.mesh.position.set(x, y, 0);
134	    b.mesh.rotation.set(0, 0, -angle);
135	    b.mesh.visible = true;
136	    b.trail = this.vfx.trails.acquire({ color: COLORS.BULLET_PLAYER, width: 0.16, emissiveIntensity: 2.2, fadeTime: 0.2 });
137	    if (b.trail) this.vfx.trails.push(b.trail, x, y - 0.3, 0);
138	    return b;
139	  }
140	
141	  spawnInvader(x, y, kind, speed) {
142	    const b = this.invaderPool.acquire();
143	    if (!b) return null;
144	    b.x = x;
145	    b.x0 = x;
146	    b.y = y;
147	    b.prevX = x;
148	    b.prevY = y;
149	    b.vy = -speed;
150	    b.age = 0;
151	    b.kind = kind;
152	    b.mesh.geometry = this.invaderGeometries[kind] || this.invaderGeometries.plunger;
153	    b.mesh.position.set(x, y, 0);
154	    b.mesh.rotation.set(0, 0, 0);
155	    b.mesh.scale.set(1, 1, 1);
156	    b.mesh.visible = true;
157	    return b;
158	  }
159	
160	  releasePlayer(b) {
161	    this.playerPool.release(b);
162	  }
163	
164	  releaseInvader(b) {
165	    this.invaderPool.release(b);
166	  }
167	
168	  fixedUpdate(step) {
169	    this.playerPool.forEach((b) => {
170	      b.prevX = b.x;
171	      b.prevY = b.y;
172	      b.x += b.vx * step;
173	      b.y += b.vy * step;
174	      b.age += step;
175	      b.mesh.position.set(b.x, b.y, 0);
176	      if (b.y > WORLD.CULL_TOP_Y || Math.abs(b.x) > WORLD.HALF_WIDTH + 2) this.playerPool.release(b);
177	    });
178	
179	    this.invaderPool.forEach((b) => {
180	      b.prevX = b.x;
181	      b.prevY = b.y;
182	      b.age += step;
183	      b.y += b.vy * step;
184	      if (b.kind === 'squiggly') {
185	        b.x = b.x0 + INVADER_FIRE.ZIGZAG_AMP * Math.sin(Math.PI * 2 * INVADER_FIRE.ZIGZAG_HZ * b.age);
186	      }
187	      b.mesh.position.set(b.x, b.y, 0);
188	      if (b.kind === 'rolling') b.mesh.rotation.y += 14 * step;
189	      else if (b.kind === 'plunger') b.mesh.scale.y = 1 + 0.25 * Math.sin(b.age * 30);
190	      if (b.y < WORLD.CULL_BOTTOM_Y) this.invaderPool.release(b);
191	    });
192	  }
193	
194	  /** Per-frame: feed trails with the latest bolt positions. */
195	  update() {
196	    this.playerPool.forEach((b) => {
197	      if (b.trail) this.vfx.trails.push(b.trail, b.x, b.y - 0.3, 0);
198	    });
199	  }
200	
201	  bulletAabb(b, out) {
202	    return setAabb(out, b.x, b.y, b.halfW, b.halfH);
203	  }
204	
205	  clearInvaderBullets() {
206	    this.invaderPool.releaseAll();
207	  }
208	
209	  clearAll() {
210	    this.playerPool.releaseAll();
211	    this.invaderPool.releaseAll();
212	  }
213	
214	  dispose() {
215	    this.playerPool.dispose((b) => this.scene.remove(b.mesh));
216	    this.invaderPool.dispose((b) => this.scene.remove(b.mesh));
217	  }
218	}

1	// The mystery ship: lathe-profile saucer with a glass dome, rotating neon rim lights and a
2	// scanning beam. Crosses the top lane on a timer while at least 8 invaders remain.
3	import { Group, Mesh, LatheGeometry, SphereGeometry, ConeGeometry, BoxGeometry, Vector2, Vector3 } from 'three';
4	import { chromeMaterial, neonMaterial, glassMaterial } from '@shared/procgen/MaterialLibrary.js';
5	import { mergeGeometries } from '@shared/procgen/GeometryUtils.js';
6	import { setAabb } from '@shared/math/Collision.js';
7	import { WORLD, UFO, COLORS } from '../config.js';
8	
9	const _pos = new Vector3();
10	
11	export class UFOShip {
12	  /**
13	   * @param {import('three').Scene} scene
14	   * @param {import('@shared/core/ResourceTracker.js').ResourceTracker} tracker
15	   * @param {import('@shared/procgen/Random.js').Random} random
16	   * @param {import('@shared/core/EventBus.js').EventBus} events
17	   * @param {import('@shared/vfx/VFXDirector.js').VFXDirector} vfx
18	   */
19	  constructor(scene, tracker, random, events, vfx) {
20	    this.scene = scene;
21	    this.random = random;
22	    this.events = events;
23	    this.vfx = vfx;
24	
25	    this.group = new Group();
26	    this.group.name = 'UFO';
27	
28	    const profile = [
29	      new Vector2(0.0, -0.25),
30	      new Vector2(0.9, -0.2),
31	      new Vector2(1.6, 0.0),
32	      new Vector2(1.2, 0.25),
33	      new Vector2(0.6, 0.45),
34	      new Vector2(0.0, 0.5),
35	    ];
36	    const hullGeometry = tracker.track(new LatheGeometry(profile, 36));
37	    this.hullMaterial = tracker.track(chromeMaterial({ color: 0xd9dcff, roughness: 0.22, metalness: 0.95 }));
38	    this.hull = new Mesh(hullGeometry, this.hullMaterial);
39	    this.group.add(this.hull);
40	
41	    const domeGeometry = tracker.track(new SphereGeometry(0.5, 24, 14, 0, Math.PI * 2, 0, Math.PI * 0.5));
42	    this.domeMaterial = tracker.track(glassMaterial({ color: COLORS.UFO, emissive: COLORS.UFO, intensity: 1.4, opacity: 0.5 }));
43	    this.dome = new Mesh(domeGeometry, this.domeMaterial);
44	    this.dome.position.y = 0.32;
45	    this.group.add(this.dome);
46	
47	    // Eight rim lights merged into one emissive mesh that spins.
48	    const lights = [];
49	    for (let k = 0; k < 8; k++) {
50	      const a = (k / 8) * Math.PI * 2;
51	      const box = new BoxGeometry(0.22, 0.12, 0.22);
52	      box.rotateY(-a);
53	      box.translate(Math.cos(a) * 1.28, 0.06, Math.sin(a) * 1.28);
54	      lights.push(box);
55	    }
56	    const rimGeometry = tracker.track(mergeGeometries(lights));
57	    this.rimMaterial = tracker.track(neonMaterial({ color: 0x140408, emissive: COLORS.UFO, intensity: 2.0 }));
58	    this.rim = new Mesh(rimGeometry, this.rimMaterial);
59	    this.group.add(this.rim);
60	
61	    // Scanning beam: an inverted cone hanging below the hull.
62	    const beamGeometry = tracker.track(new ConeGeometry(1.3, 3.2, 24, 1, true));
63	    this.beamMaterial = tracker.track(glassMaterial({ color: COLORS.UFO, emissive: COLORS.UFO, intensity: 0.9, opacity: 0.16 }));
64	    this.beam = new Mesh(beamGeometry, this.beamMaterial);
65	    this.beam.position.y = -1.85; // apex (+Y) sits under the hull, the base opens downward
66	    this.group.add(this.beam);
67	
68	    this.group.visible = false;
69	    scene.add(this.group);
70	    tracker.track(this.group);
71	
72	    this.active = false;
73	    this.x = 0;
74	    this.dir = 1;
75	    this.timer = UFO.FIRST_DELAY;
76	    this.clock = 0;
77	    this.trail = null;
78	  }
79	
80	  reset() {
81	    this.active = false;
82	    this.group.visible = false;
83	    this.timer = UFO.FIRST_DELAY;
84	    this._dropTrail();
85	  }
86	
87	  _dropTrail() {
88	    if (this.trail) {
89	      this.vfx.trails.release(this.trail);
90	      this.trail = null;
91	    }
92	  }
93	
94	  spawn() {
95	    this.active = true;
96	    this.dir = this.random.sign();
97	    this.x = -this.dir * (WORLD.HALF_WIDTH + 3);
98	    this.group.visible = true;
99	    this.group.position.set(this.x, WORLD.UFO_Y, 0);
100	    this._dropTrail();
101	    this.trail = this.vfx.trails.acquire({ color: COLORS.UFO, width: 0.5, emissiveIntensity: 1.6, fadeTime: 0.5, minSegment: 0.15 });
102	    this.events.emit('ufo:spawn', { x: this.x, dir: this.dir });
103	  }
104	
105	  aabb(out) {
106	    return setAabb(out, this.x, WORLD.UFO_Y, UFO.HALF_W, UFO.HALF_H);
107	  }
108	
109	  fixedUpdate(step, aliveCount) {
110	    if (!this.active) {
111	      this.timer -= step;
112	      if (this.timer <= 0) {
113	        if (aliveCount >= UFO.MIN_ALIVE) this.spawn();
114	        else this.timer = 2;
115	      }
116	      return;
117	    }
118	    this.x += this.dir * UFO.SPEED * step;
119	    if (Math.abs(this.x) > WORLD.HALF_WIDTH + 3.5) {
120	      this.active = false;
121	      this.group.visible = false;
122	      this.timer = this.random.range(UFO.INTERVAL_MIN, UFO.INTERVAL_MAX);
123	      this._dropTrail();
124	      this.events.emit('ufo:escaped', {});
125	    }
126	  }
127	
128	  update(dt) {
129	    if (!this.active) return;
130	    this.clock += dt;
131	    const bob = Math.sin(this.clock * 4) * 0.15;
132	    this.group.position.set(this.x, WORLD.UFO_Y + bob, 0);
133	    this.rim.rotation.y += dt * 3.5;
134	    this.beam.rotation.y += dt * 1.2;
135	    this.beamMaterial.opacity = 0.12 + 0.08 * Math.sin(this.clock * 9);
136	    this.rimMaterial.emissiveIntensity = 1.8 + 0.6 * Math.sin(this.clock * 14);
137	    if (this.trail) {
138	      _pos.set(this.x - this.dir * 1.2, WORLD.UFO_Y + bob, 0);
139	      this.vfx.trails.push(this.trail, _pos.x, _pos.y, _pos.z);
140	    }
141	  }
142	
143	  /**
144	   * Destroy the ship. Preserves the cabinet's easter egg: the 23rd shot, then every 15th, is
145	   * worth 300; otherwise a weighted random pick.
146	   */
147	  hit(shotsFired) {
148	    this.active = false;
149	    this.group.visible = false;
150	    this.timer = this.random.range(UFO.INTERVAL_MIN, UFO.INTERVAL_MAX);
151	    this._dropTrail();
152	    const easter =
153	      shotsFired === UFO.EASTER_FIRST || (shotsFired > UFO.EASTER_FIRST && (shotsFired - UFO.EASTER_FIRST) % UFO.EASTER_EVERY === 0);
154	    const points = easter ? UFO.EASTER_SCORE : this.random.weighted(UFO.SCORES, UFO.WEIGHTS);
155	    return { points, easter, x: this.x, y: WORLD.UFO_Y };
156	  }
157	
158	  dispose() {
159	    this._dropTrail();
160	    this.scene.remove(this.group);
161	  }
162	}

