1	// The Engine owns the render loop and every cross-cutting subsystem. Per frame:
2	//   input.update() → hitStop → fixed-step accumulator (game.fixedUpdate ×N) → game.update →
3	//   vfx.update → rig.apply() → composer.render()
4	// Real dt is clamped so a background tab never produces a giant step; scaled dt honours hit-stop.
5	import { Scene, PerspectiveCamera } from 'three';
6	import { createRenderer } from '../render/RendererFactory.js';
7	import { PostPipeline } from '../render/PostPipeline.js';
8	import { CameraRig } from '../render/CameraRig.js';
9	import { createNeonEnvironment } from '../render/EnvironmentMap.js';
10	import { InputManager } from '../input/InputManager.js';
11	import { AudioEngine } from '../audio/AudioEngine.js';
12	import { HitStop } from '../vfx/HitStop.js';
13	import { VFXDirector } from '../vfx/VFXDirector.js';
14	import { EventBus } from './EventBus.js';
15	import { ResourceTracker } from './ResourceTracker.js';
16	
17	export class Engine {
18	  constructor({
19	    container,
20	    fixedStep = 1 / 120,
21	    maxFrameTime = 0.1,
22	    maxSubSteps = 8,
23	    pixelRatioCap = 2,
24	    clearColor = 0x05060f,
25	    camera = { fov: 45, near: 0.1, far: 400 },
26	    bloom = undefined,
27	    retro = undefined,
28	    samples = 4,
29	    particleCapacity = 500,
30	    environment = {},
31	    environmentIntensity = 0.55,
32	  }) {
33	    if (!container) throw new Error('Engine: container element is required');
34	    this.container = container;
35	    this.fixedStep = fixedStep;
36	    this.maxFrameTime = maxFrameTime;
37	    this.maxSubSteps = maxSubSteps;
38	
39	    this.renderer = createRenderer({ container, pixelRatioCap, clearColor });
40	    this.scene = new Scene();
41	    this.camera = new PerspectiveCamera(camera.fov, this.aspect, camera.near, camera.far);
42	    this.rig = new CameraRig(this.camera);
43	    this.environment = environment === false ? null : createNeonEnvironment(this.renderer, environment);
44	    if (this.environment) {
45	      this.scene.environment = this.environment.texture;
46	      if ('environmentIntensity' in this.scene) this.scene.environmentIntensity = environmentIntensity;
47	    }
48	    this.composer = new PostPipeline(this.renderer, this.scene, this.camera, { bloom, retro, samples });
49	    this.input = new InputManager();
50	    this.audio = new AudioEngine();
51	    this.events = new EventBus();
52	    this.resources = new ResourceTracker();
53	    this.hitStop = new HitStop();
54	    this.vfx = new VFXDirector({
55	      scene: this.scene,
56	      camera: this.camera,
57	      rig: this.rig,
58	      container,
59	      hitStop: this.hitStop,
60	      particleCapacity,
61	    });
62	
63	    this.game = null;
64	    this.running = false;
65	    this.time = 0;
66	    this.realTime = 0;
67	    this.frame = 0;
68	    this.timeScale = 1;
69	    this.accumulator = 0;
70	    this.fps = 0;
71	    this._fpsAccum = 0;
72	    this._fpsFrames = 0;
73	    this._last = 0;
74	    this._raf = 0;
75	
76	    this._frame = (now) => this._tick(now);
77	    this._onResize = () => this._resize();
78	    this._onVisibility = () => {
79	      const hidden = document.hidden;
80	      if (!hidden) this._last = performance.now();
81	      this.events.emit('engine:visibility', { hidden });
82	    };
83	    this._onGesture = () => {
84	      this.audio.unlock();
85	    };
86	
87	    window.addEventListener('resize', this._onResize);
88	    document.addEventListener('visibilitychange', this._onVisibility);
89	    window.addEventListener('keydown', this._onGesture, { passive: true });
90	    window.addEventListener('pointerdown', this._onGesture, { passive: true });
91	    window.addEventListener('touchstart', this._onGesture, { passive: true });
92	
93	    this._resize();
94	  }
