1	// Unified dual-input controller. Keyboard (WASD / arrows) and Gamepad API are folded into named
2	// actions with per-frame edge detection. `takePress` is a latched edge for fixed-step consumers so
3	// a tap is never lost on a frame in which zero simulation steps run.
4	import { KeyboardSource } from './KeyboardSource.js';
5	import { GamepadSource } from './GamepadSource.js';
6	
7	export const Actions = Object.freeze({
8	  LEFT: 'left',
9	  RIGHT: 'right',
10	  UP: 'up',
11	  DOWN: 'down',
12	  FIRE: 'fire',
13	  ALT_FIRE: 'altFire',
14	  CONFIRM: 'confirm',
15	  BACK: 'back',
16	  PAUSE: 'pause',
17	});
18	
19	const ACTION_LIST = Object.values(Actions);
20	
21	const DEFAULT_KEYS = {
22	  [Actions.LEFT]: ['ArrowLeft', 'KeyA'],
23	  [Actions.RIGHT]: ['ArrowRight', 'KeyD'],
24	  [Actions.UP]: ['ArrowUp', 'KeyW'],
25	  [Actions.DOWN]: ['ArrowDown', 'KeyS'],
26	  [Actions.FIRE]: ['Space', 'KeyJ', 'KeyZ', 'ControlLeft', 'ControlRight'],
27	  [Actions.ALT_FIRE]: ['ShiftLeft', 'ShiftRight', 'KeyK', 'KeyX'],
28	  [Actions.CONFIRM]: ['Enter', 'Space', 'NumpadEnter'],
29	  [Actions.BACK]: ['Escape', 'Backspace'],
30	  [Actions.PAUSE]: ['Escape', 'KeyP'],
31	};
32	
33	const DEFAULT_BUTTONS = {
34	  [Actions.LEFT]: [14],
35	  [Actions.RIGHT]: [15],
36	  [Actions.UP]: [12],
37	  [Actions.DOWN]: [13],
38	  [Actions.FIRE]: [0, 2, 7, 5],
39	  [Actions.ALT_FIRE]: [1, 3, 6, 4],
40	  [Actions.CONFIRM]: [0, 9],
41	  [Actions.BACK]: [1],
42	  [Actions.PAUSE]: [9],
43	};
44	
45	// Stick directions also drive the digital directional actions (for menus and 4-way games).
46	const STICK_THRESHOLD = 0.5;
47	
48	export class InputManager {
49	  constructor({ target = window, deadzone = 0.2, keys = DEFAULT_KEYS, buttons = DEFAULT_BUTTONS } = {}) {
50	    this.keyboard = new KeyboardSource(target);
51	    this.gamepad = new GamepadSource({ deadzone });
52	    this.keys = keys;
53	    this.buttons = buttons;
54	    this.activeDevice = 'keyboard';
55	    this._state = {};
56	    for (const a of ACTION_LIST) {
57	      this._state[a] = { held: false, pressed: false, released: false, latched: false };
58	    }
59	    this._anyPressed = false;
60	  }
61	
62	  /** Poll devices and compute edges. Call exactly once per rendered frame, before any queries. */
63	  update() {
64	    this.gamepad.poll();
65	    this._anyPressed = false;
66	    const gp = this.gamepad;
67	    const kb = this.keyboard;
68	
69	    if (gp.connected && gp.lastActivity > kb.lastActivity) this.activeDevice = 'gamepad';
70	    else if (kb.lastActivity > 0) this.activeDevice = 'keyboard';
71	
72	    const sx = gp.axis(0);
73	    const sy = gp.axis(1);
74	
75	    for (let i = 0; i < ACTION_LIST.length; i++) {
76	      const action = ACTION_LIST[i];
77	      const s = this._state[action];
78	      let now = kb.anyDown(this.keys[action]);
79	      if (!now && gp.connected) {
80	        const list = this.buttons[action];
81	        for (let b = 0; b < list.length; b++) {
82	          if (gp.isDown(list[b])) {
83	            now = true;
84	            break;
85	          }
86	        }
87	        if (!now) {
88	          if (action === Actions.LEFT && sx < -STICK_THRESHOLD) now = true;
89	          else if (action === Actions.RIGHT && sx > STICK_THRESHOLD) now = true;
90	          else if (action === Actions.UP && sy < -STICK_THRESHOLD) now = true;
91	          else if (action === Actions.DOWN && sy > STICK_THRESHOLD) now = true;
92	        }
93	      }
94	      s.pressed = now && !s.held;
95	      s.released = !now && s.held;
96	      s.held = now;
97	      if (s.pressed) {
98	        s.latched = true;
99	        this._anyPressed = true;
100	      }
101	    }
102	    kb.endFrame();
103	  }
104	
105	  held(action) {
106	    return this._state[action].held;
107	  }
108	
109	  /** True only on the frame the action went down. */
110	  pressed(action) {
111	    return this._state[action].pressed;
112	  }
113	
114	  released(action) {
115	    return this._state[action].released;
116	  }
117	
118	  /** Latched edge: true once per press, regardless of how many frames passed since the press. */
119	  takePress(action) {
120	    const s = this._state[action];
121	    if (s.latched) {
122	      s.latched = false;
123	      return true;
124	    }
125	    return false;
126	  }
127	
128	  /** Discard latched presses (call on state transitions so a menu confirm doesn't fire a shot). */
129	  flush() {
130	    for (let i = 0; i < ACTION_LIST.length; i++) this._state[ACTION_LIST[i]].latched = false;
131	  }
132	
133	  /** Any action pressed this frame (used for "press any key" and audio unlock). */
134	  anyPressed() {
135	    return this._anyPressed;
136	  }
137	
138	  /**
139	   * Analog axis in [-1, 1]. 'moveX' / 'moveY' combine digital keys with the left stick;
140	   * whichever has the larger magnitude wins. +Y is up.
141	   */
142	  axis(name) {
143	    const gp = this.gamepad;
144	    if (name === 'moveX') {
145	      const kb = (this.held(Actions.RIGHT) ? 1 : 0) - (this.held(Actions.LEFT) ? 1 : 0);
146	      const stick = gp.connected ? gp.axis(0) : 0;
147	      return Math.abs(stick) > Math.abs(kb) ? stick : kb;
148	    }
149	    if (name === 'moveY') {
150	      const kb = (this.held(Actions.UP) ? 1 : 0) - (this.held(Actions.DOWN) ? 1 : 0);
151	      const stick = gp.connected ? -gp.axis(1) : 0;
152	      return Math.abs(stick) > Math.abs(kb) ? stick : kb;
153	    }
154	    if (name === 'lookX') return gp.connected ? gp.axis(2) : 0;
155	    if (name === 'lookY') return gp.connected ? -gp.axis(3) : 0;
156	    return 0;
157	  }
158	
159	  rumble(duration, weak, strong) {
160	    this.gamepad.rumble(duration, weak, strong);
161	  }
162	
163	  dispose() {
164	    this.keyboard.dispose();
165	    this.gamepad.dispose();
166	  }
167	}

