async (page) => {
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));
  await page.goto('http://127.0.0.1:5179/Space_Invaders/?seed=11');
  await page.waitForFunction(() => window.__SI__ && window.__SI__.snapshot().state === 'TITLE');
  const snap = () => page.evaluate(() => window.__SI__.snapshot());
  const waitState = async (s, ms = 15000) => page.waitForFunction((s) => window.__SI__.snapshot().state === s, s, { timeout: ms });
  const log = [];
  const mem0 = await page.evaluate(() => window.__SI__.memory());

  // 1. Title → start with a real Enter tap.
  await page.keyboard.press('Enter');
  await waitState('WAVE_INTRO');
  log.push('start ok → WAVE_INTRO');
  await waitState('PLAY');
  log.push('PLAY reached');

  // 2. Real play: sweep left/right while holding fire for ~7 s.
  await page.keyboard.down('Space');
  for (let i = 0; i < 6; i++) {
    const key = i % 2 === 0 ? 'ArrowLeft' : 'ArrowRight';
    await page.keyboard.down(key);
    await page.waitForTimeout(1100);
    await page.keyboard.up(key);
