  log.push(`after 6.6s of play: score=${afterPlay.score} invaders=${afterPlay.invaders} lives=${afterPlay.lives} state=${afterPlay.state}`);

  if (afterPlay.state === 'PLAY') {
    await page.keyboard.press('Escape');
    await waitState('PAUSED', 3000);
    await page.keyboard.press('Escape');
    await waitState('PLAY', 3000);
    log.push('pause/resume ok');
  }

  for (let w = 1; w <= 5; w++) {
    await waitState('PLAY', 20000);
    const before = await snap();
    const killed = await page.evaluate(() => window.__SI__.killAll());
    const after = await snap();
    log.push(`wave ${before.wave}: killed ${killed}, state=${after.state}, score=${after.score}`);
    if (w < 5) await waitState('WAVE_INTRO', 8000);
  }
  await waitState('VICTORY', 8000);
  const vict = await snap();
  log.push(`VICTORY score=${vict.score} lives=${vict.lives}`);
  await page.waitForTimeout(1600);
  await page.screenshot({ path: '.playwright-mcp/victory.png', scale: 'css' });

  // Victory → Title (2nd item) → immediately start again (tap right after tap).
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('Enter');
  await waitState('TITLE', 5000);
  await page.keyboard.press('Enter');
  await waitState('WAVE_INTRO', 5000);
  log.push('title → new game (back-to-back taps) ok');
  await waitState('PLAY', 20000);
  for (let k = 0; k < 3; k++) {
    await waitState('PLAY', 20000);
    await page.evaluate(() => window.__SI__.forceHit());
    await waitState('PLAYER_DEATH', 3000);
    log.push(`death ${k + 1}: lives=${(await snap()).lives}`);
  }
  await waitState('GAME_OVER', 8000);
  await page.waitForTimeout(1800);
  await page.screenshot({ path: '.playwright-mcp/gameover.png', scale: 'css' });
  const go = await snap();
  log.push(`GAME_OVER lives=${go.lives} score=${go.score} hi=${go.hiScore}`);

  await page.keyboard.press('Enter'); // Retry
  await waitState('WAVE_INTRO', 5000);
  await waitState('PLAY', 20000);
  await page.waitForTimeout(500);
  await page.screenshot({ path: '.playwright-mcp/play2.png', scale: 'css' });
  const mem1 = await page.evaluate(() => window.__SI__.memory());
  const fps = await page.evaluate(() => window.__SI__.engine.fps.toFixed(1));
  const particles = await page.evaluate(() => window.__SI__.engine.vfx.particles.capacity);
  return { log, errors, mem0, mem1, fps, particleCap: particles };
})(page);
