14	const _color = new Color();
15	
16	export class PostPipeline {
17	  constructor(
18	    renderer,
19	    scene,
20	    camera,
21	    {
22	      bloom = { strength: 0.75, radius: 0.4, threshold: 0.85 },
23	      retro = { aberration: 0.0012, vignette: 0.38, scanlines: 0.05, grain: 0.035, vignetteColor: 0x000000 },
24	      samples = 4,
25	      aberrationTraumaGain = 0.006,
26	      flashDecay = 4,
27	    } = {},
28	  ) {
29	    this.renderer = renderer;
30	    this.scene = scene;
31	    this.camera = camera;
32	    this.time = 0;
