34	    this.aberrationTraumaGain = aberrationTraumaGain;
35	    this.flashDecay = flashDecay;
36	    this._flashAlpha = 0;
37	
38	    renderer.getSize(_size);
39	    const pr = renderer.getPixelRatio();
40	    const width = Math.max(1, Math.floor(_size.x * pr));
41	    const height = Math.max(1, Math.floor(_size.y * pr));
42	    this.target = new WebGLRenderTarget(width, height, {
43	      type: HalfFloatType,
44	      samples: 0,
