async (page) => {
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));
  await page.goto('http://127.0.0.1:5179/Space_Invaders/?seed=11');
  await page.waitForFunction(() => window.__SI__ && window.__SI__.snapshot().state === 'TITLE');
  const waitState = async (s, ms = 15000) => page.waitForFunction((s) => window.__SI__.snapshot().state === s, s, { timeout: ms });
  await page.keyboard.press('Enter');
  await waitState('PLAY');
  // Play with fire held and strafing so particles/trails are active while measuring.
  await page.keyboard.down('Space');
  await page.keyboard.down('ArrowLeft');
  await page.waitForTimeout(900);
  await page.keyboard.up('ArrowLeft');
  await page.keyboard.down('ArrowRight');
  await page.waitForTimeout(1800);
  const fps = await page.evaluate(() => window.__SI__.engine.fps);
  await page.keyboard.up('ArrowRight');
  await page.keyboard.up('Space');
  await page.screenshot({ path: '.playwright-mcp/play3.png', scale: 'css' });
  const snap = await page.evaluate(() => window.__SI__.snapshot());
  const pr = await page.evaluate(() => window.__SI__.engine.renderer.getPixelRatio());
  return { fps: fps.toFixed(1), pr, snap, errors };
}

