  page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

  // Inject a fake gamepad before load so GamepadSource adopts it.
  await page.addInitScript(() => {
    window.__pad = { id: 'Fake Xbox', index: 0, connected: true, mapping: 'standard',
      buttons: Array.from({ length: 17 }, () => ({ pressed: false, touched: false, value: 0 })),
      axes: [0, 0, 0, 0], timestamp: 0, vibrationActuator: { playEffect: () => Promise.resolve('complete') } };
    navigator.getGamepads = () => [window.__pad, null, null, null];
  });
  await page.goto('http://127.0.0.1:5179/Space_Invaders/?seed=5');
  await page.waitForFunction(() => window.__SI__ && window.__SI__.snapshot().state === 'TITLE');
  const waitState = async (s, ms = 15000) => page.waitForFunction((s) => window.__SI__.snapshot().state === s, s, { timeout: ms });
  const press = async (i, ms = 120) => {
    await page.evaluate((i) => { window.__pad.buttons[i].pressed = true; window.__pad.buttons[i].value = 1; }, i);
    await page.waitForTimeout(ms);
    await page.evaluate((i) => { window.__pad.buttons[i].pressed = false; window.__pad.buttons[i].value = 0; }, i);
    await page.waitForTimeout(60);
  };
  // A button (0) = confirm on the title menu.
  await press(0);
  await waitState('WAVE_INTRO', 5000);
  await waitState('PLAY');
  const device = await page.evaluate(() => window.__SI__.engine.input.activeDevice);
  // Left stick 60 % → move left; then dead-zone check at 10 %.
  await page.evaluate(() => { window.__pad.axes[0] = -0.6; });
  await page.waitForTimeout(700);
  const x1 = await page.evaluate(() => window.__SI__.snapshot().playerX);
  await page.evaluate(() => { window.__pad.axes[0] = 0.1; });
  await page.waitForTimeout(400);
  const x2 = await page.evaluate(() => window.__SI__.snapshot().playerX);
  // D-pad right (15) held → move right; RT (7) fires.
  await page.evaluate(() => { window.__pad.buttons[15].pressed = true; window.__pad.buttons[15].value = 1; });
  await page.waitForTimeout(500);
  await page.evaluate(() => { window.__pad.buttons[15].pressed = false; window.__pad.buttons[15].value = 0; });
  const x3 = await page.evaluate(() => window.__SI__.snapshot().playerX);
  const shotsBefore = await page.evaluate(() => window.__SI__.game.score.stats.shots);
  await press(7);
  await page.waitForTimeout(100);
  const shotsAfter = await page.evaluate(() => window.__SI__.game.score.stats.shots);
  // Start (9) pauses; B (1) resumes via onBack.
  await press(9);
  await waitState('PAUSED', 3000);
  await press(1);
  await waitState('PLAY', 3000);
  return { device, x1: x1.toFixed(2), x2: x2.toFixed(2), x3: x3.toFixed(2), shotsBefore, shotsAfter, errors };
}

