async (page) => {
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));
  await page.goto('http://127.0.0.1:5179/Space_Invaders/?seed=3');
  await page.waitForFunction(() => window.__SI__ && window.__SI__.snapshot().state === 'TITLE');
  const waitState = async (s, ms = 15000) => page.waitForFunction((s) => window.__SI__.snapshot().state === s, s, { timeout: ms });

  // Corner visibility check: project the playfield extremes at several viewport sizes.
  const corners = async () => page.evaluate(() => {
    const e = window.__SI__.engine; const V = new e.camera.position.constructor();
    const pts = { left: [-16, 0, 0], right: [16, 0, 0], player: [0, -0.5, 0], ufo: [0, 23.5, 0], topLeft: [-16, 24, 0], topRight: [16, 24, 0] };
    const out = {};
    for (const k in pts) { V.set(...pts[k]).project(e.camera); out[k] = [+(V.x).toFixed(2), +(V.y).toFixed(2)]; }
    return out;
  });
  const fits = {};
  for (const [w, h] of [[1920, 1080], [1280, 720], [1000, 1000], [800, 1200]]) {
    await page.setViewportSize({ width: w, height: h });
    await page.waitForTimeout(250);
    fits[`${w}x${h}`] = await corners();
  }
  await page.setViewportSize({ width: 1600, height: 900 });
  await page.waitForTimeout(250);
  await page.screenshot({ path: '.playwright-mcp/title3.png', scale: 'css' });

  // Memory stability across repeated games, then full teardown.
  const mem = () => page.evaluate(() => window.__SI__.memory());
  const cycle = async () => {
    await page.keyboard.press('Enter');
    await waitState('PLAY', 20000);
    await page.evaluate(() => window.__SI__.killAll());
    await waitState('WAVE_INTRO', 8000);
    await waitState('PLAY', 20000);
    for (let k = 0; k < 3; k++) { await waitState('PLAY', 20000); await page.evaluate(() => window.__SI__.forceHit()); await waitState('PLAYER_DEATH', 3000); }
    await waitState('GAME_OVER', 8000);
    await page.waitForTimeout(1700);
    await page.keyboard.press('ArrowDown'); // Title
    await page.keyboard.press('Enter');
    await waitState('TITLE', 5000);
    return await mem();
  };
  const m1 = await cycle();
  const m2 = await cycle();
  const m3 = await cycle();
  const disposed = await page.evaluate(() => { const e = window.__SI__.engine; e.dispose(); return { ...e.renderer.info.memory, canvasInDom: !!document.querySelector('canvas'), uiInDom: !!document.querySelector('.ui-root') }; });
  return { fits, m1, m2, m3, disposed, errors };
}

