async (page) => {
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));
  await page.goto('http://127.0.0.1:5179/Space_Invaders/?seed=21');
  await page.waitForFunction(() => window.__SI__ && window.__SI__.snapshot().state === 'TITLE');
  const waitState = async (s, ms = 15000) => page.waitForFunction((s) => window.__SI__.snapshot().state === s, s, { timeout: ms });
  const log = [];
  await page.keyboard.press('Enter');
  await waitState('PLAY', 20000);

  // 1. Power-up: spawn a SPREAD pickup just above the cannon and let it fall into it.
  await page.evaluate(() => { const g = window.__SI__.game; g.powerups.spawn(g.player.x, 3.5, 'SPREAD'); });
  await page.waitForFunction(() => window.__SI__.game.player.power.type === 'SPREAD', null, { timeout: 5000 });
  await page.keyboard.press('Space');
  await page.waitForTimeout(150);
  const spreadShots = await page.evaluate(() => window.__SI__.game.projectiles.playerLiveCount);
  log.push(`SPREAD collected; one press fired ${spreadShots} bolts`);

  // 2. Shield: absorbs a hit without losing a life.
  await page.evaluate(() => { const g = window.__SI__.game; g.powerups.spawn(g.player.x, 3.5, 'SHIELD'); });
  await page.waitForFunction(() => window.__SI__.game.player.shield === true, null, { timeout: 5000 });
  const livesBefore = await page.evaluate(() => window.__SI__.snapshot().lives);
  await page.evaluate(() => window.__SI__.forceHit());
  await page.waitForTimeout(300);
  const afterShield = await page.evaluate(() => ({ ...window.__SI__.snapshot(), shield: window.__SI__.game.player.shield }));
  log.push(`SHIELD: lives ${livesBefore} → ${afterShield.lives}, state=${afterShield.state}, shield now=${afterShield.shield}`);

  // 3. UFO: force a spawn, then fire a bolt that intercepts it.
  await page.evaluate(() => { const g = window.__SI__.game; g.ufo.timer = 0; });
  await page.waitForFunction(() => window.__SI__.game.ufo.active, null, { timeout: 5000 });
  const scoreBeforeUfo = await page.evaluate(() => window.__SI__.snapshot().score);
  await page.evaluate(() => {
    const g = window.__SI__.game; const u = g.ufo;
    const travel = (23.5 - 1.75) / 30;               // bolt flight time to the UFO lane
    const lead = u.x + u.dir * 6.5 * travel;          // where the saucer will be
    g.projectiles.spawnPlayer(lead, 1.75, 0);
  });
  await page.waitForFunction(() => !window.__SI__.game.ufo.active, null, { timeout: 4000 });
  const afterUfo = await page.evaluate(() => ({ score: window.__SI__.snapshot().score, ufoKills: window.__SI__.game.score.stats.ufoKills }));
  log.push(`UFO: score ${scoreBeforeUfo} → ${afterUfo.score} (ufoKills=${afterUfo.ufoKills})`);
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.playwright-mcp/ufo.png', scale: 'css' });

  // 4. Invasion: drop the formation to the bunker line and watch it eat cells, then reach the ground.
  const cellsBefore = await page.evaluate(() => window.__SI__.snapshot().bunkerCells);
  await page.evaluate(() => { const g = window.__SI__.game; g.formation.originY = 4.0 + 4 * 1.8; });
  await page.waitForFunction((c) => window.__SI__.snapshot().bunkerCells < c, cellsBefore, { timeout: 5000 });
  const cellsAfter = await page.evaluate(() => window.__SI__.snapshot().bunkerCells);
  log.push(`bunkers eaten by formation: ${cellsBefore} → ${cellsAfter}`);
  await page.evaluate(() => { const g = window.__SI__.game; g.formation.originY = 1.5 + 4 * 1.8 + 0.9; });
  await waitState('GAME_OVER', 30000);
  const reason = await page.evaluate(() => window.__SI__.game.gameOverReason);
  log.push(`GAME_OVER reason=${reason}`);
  await page.waitForTimeout(1800);
  await page.screenshot({ path: '.playwright-mcp/invaded.png', scale: 'css' });
  return { log, errors };
}

